; chget.asm -- chapter 16: waiting for a key
; generated by gen16.py
        INCLUDE "msx.inc"
        OUTPUT "chget.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
; CHGET waits for a key in the buffer that the BIOS's interrupt routine
; fills. The program calls it as INIT leaves the machine: interrupts off.
init:   di
        ld sp, SYS_AREA
c1:     call CHGET              ; wait for a key
c2:     ld (RESULTS), a         ; its code
        VDP_REG 7, LIGHT_GREEN  ; the border light green: a key came
stop:   jr stop
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
